// ===== p221 : les écritures des fiches marchent hors ligne — les quatre polices (Petit Formal Script, Caveat, Uncial Antiqua, Kalam ;
// licence SIL Open Font License, paquets @fontsource) sont intégrées au jeu, sous-ensemble latin ; on ne dépend plus de Google Fonts. =====
{const st=document.createElement('style');st.id='polices221';st.textContent="@font-face{font-family:'Petit Formal Script';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Caveat';font-style:normal;font-weight:500;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Uncial Antiqua';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Kalam';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}";document.head.appendChild(st);
 setInterval(()=>{try{document.querySelectorAll('link[href*="fonts.googleapis"]').forEach(l=>{if(/Petit\+Formal|Uncial|Kalam/.test(l.href))l.remove()})}catch(e){}},2000)}
